<!doctype html><html><head><meta charset="utf-8"><title>Service Mark Calculation</title><style>body{font-family:Arial,sans-serif;font-size:12px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #333;padding:6px;text-align:left}.right{text-align:right}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print</button><h2>Teacher Service Mark Calculation</h2><p>Reference: #{{ $calculation->id }} | Employee: {{ $calculation->employee_id }} | Processing province: {{ $calculation->processingProvince->province_name }} | Date: {{ $calculation->calculation_date->format('Y-m-d') }}</p><table><thead><tr><th>Period</th><th>School</th><th>Province</th><th>Rate type</th><th>Months</th><th>Mark/year</th><th>Score</th></tr></thead><tbody>@foreach($calculation->lines as $line)<tr><td>{{ $line->period_start->format('Y-m-d') }} - {{ $line->period_end->format('Y-m-d') }}</td><td>{{ $line->workplace_name }}</td><td>{{ $line->province_name }}</td><td>{{ ucfirst($line->mark_type) }}</td><td class="right">{{ $line->completed_months }}</td><td class="right">{{ number_format($line->mark_snapshot,4) }}</td><td class="right">{{ number_format($line->score,4) }}</td></tr>@endforeach</tbody><tfoot><tr><th colspan="6" class="right">Total</th><th class="right">{{ number_format($calculation->total_score,2) }}</th></tr></tfoot></table><p>Formula: mark per year × completed months ÷ 12</p><p>Created by: {{ $calculation->creator?->full_name ?? $calculation->created_by }}</p></body></html>

